import{_ as t,a,o,a6 as r}from"./chunks/framework.CJDy2q7X.js";const u=JSON.parse('{"title":"Sections","description":"","frontmatter":{"outline":false,"apiType":"graphql"},"headers":[],"relativePath":"api/graphql-api/shop/sections/index.md","filePath":"api/graphql-api/shop/sections/index.md","lastUpdated":1789385991000}'),n={name:"api/graphql-api/shop/sections/index.md"};function s(d,e,i,c,h,l){return o(),a("div",null,e[0]||(e[0]=[r('<h1 id="sections" tabindex="-1">Sections <a class="header-anchor" href="#sections" aria-label="Permalink to &quot;Sections&quot;">​</a></h1><p>Sections are the blocks a storefront page is built from — carousels, static content, the footer links. A merchandiser arranges them per channel, and the storefront draws them in the order given.</p><h2 id="what-is-returned" tabindex="-1">What is returned <a class="header-anchor" href="#what-is-returned" aria-label="Permalink to &quot;What is returned&quot;">​</a></h2><p>The queries return the <strong>published</strong> sections of the current channel&#39;s active theme:</p><ul><li><strong>Only published content</strong> — unpublished edits held in the admin never appear.</li><li><strong>Only the active theme&#39;s sections</strong> — a channel that switches theme keeps its old sections, but they stop being returned.</li><li><strong>Only sections that are switched on</strong> — a section turned off is absent rather than flagged.</li></ul><h2 id="types" tabindex="-1">Types <a class="header-anchor" href="#types" aria-label="Permalink to &quot;Types&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Type</th><th>What it holds</th></tr></thead><tbody><tr><td><code>image_carousel</code></td><td>Slides, each with an image and a link.</td></tr><tr><td><code>product_carousel</code></td><td>A product filter to run and draw as a slider.</td></tr><tr><td><code>category_carousel</code></td><td>A category filter to run and draw as a slider.</td></tr><tr><td><code>footer_links</code></td><td>Footer link columns.</td></tr><tr><td><code>static_content</code></td><td>Free HTML and CSS.</td></tr><tr><td><code>services_content</code></td><td>Service badges, each with an icon.</td></tr></tbody></table><p><code>type</code> decides the shape of <code>options</code>, so a client switches on it when rendering.</p><h2 id="content-and-locale" tabindex="-1">Content and locale <a class="header-anchor" href="#content-and-locale" aria-label="Permalink to &quot;Content and locale&quot;">​</a></h2><p>Content is stored per locale. Each section carries <code>translation</code> for the current locale and <code>translations</code> for every locale it has content in. <code>options</code> is a JSON-encoded string; parse it before use.</p><h2 id="queries" tabindex="-1">Queries <a class="header-anchor" href="#queries" aria-label="Permalink to &quot;Queries&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Query</th><th>Purpose</th></tr></thead><tbody><tr><td><a href="/api/graphql-api/shop/sections/list.html">sections</a></td><td>The published sections of the current channel</td></tr><tr><td><a href="/api/graphql-api/shop/sections/detail.html">section</a></td><td>One section by ID</td></tr></tbody></table><p>Both are public — they need only the storefront key, no customer token.</p>',13)]))}const b=t(n,[["render",s]]);export{u as __pageData,b as default};
